---
import Layout from '../layouts/Layout.astro';
import { successMessage, trimValues, validateContact, type ContactErrors, type ContactValues } from '../lib/contact';

export const prerender = false;

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success: string | undefined;

if (Astro.request.method === 'POST') {
  let form: FormData | undefined;
  try {
    form = await Astro.request.formData();
  } catch {
    form = undefined;
  }
  const field = (key: string) => {
    const value = form?.get(key);
    return typeof value === 'string' ? value : '';
  };
  values = { name: field('name'), email: field('email'), message: field('message') };
  errors = validateContact(values);
  const ok = Object.keys(errors).length === 0;
  if (ok) success = successMessage(values.name);

  if (Astro.request.headers.get('accept')?.includes('application/json')) {
    return Response.json(ok ? { ok, message: success } : { ok, errors }, { status: ok ? 200 : 400 });
  }
  if (ok) values = { name: '', email: '', message: '' };
  else values = { ...values, ...trimValues(values) };
} else if (Astro.request.method !== 'GET' && Astro.request.method !== 'HEAD') {
  return new Response(null, { status: 405, headers: { Allow: 'GET, HEAD, POST' } });
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p class="success" role="status" hidden={!success}>{success}</p>
  <form method="post" action="/contact" novalidate class="contact">
    <div class="field">
      <label for="name">Name</label>
      <input id="name" name="name" type="text" autocomplete="name" value={values.name}
        aria-invalid={errors.name ? 'true' : undefined} aria-describedby="name-error" />
      <span id="name-error" class="error" data-error-for="name">{errors.name}</span>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input id="email" name="email" type="email" autocomplete="email" value={values.email}
        aria-invalid={errors.email ? 'true' : undefined} aria-describedby="email-error" />
      <span id="email-error" class="error" data-error-for="email">{errors.email}</span>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea id="message" name="message" rows="6"
        aria-invalid={errors.message ? 'true' : undefined} aria-describedby="message-error">{values.message}</textarea>
      <span id="message-error" class="error" data-error-for="message">{errors.message}</span>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<style>
  .field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin-bottom: 1rem;
  }
  .error {
    color: #b00020;
  }
  .success {
    padding: 0.5rem 1rem;
    border: 1px solid #2e7d32;
    color: #2e7d32;
  }
</style>

<script>
  import { successMessage, validateContact, type ContactErrors, type ContactValues } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('form.contact');
  const status = document.querySelector<HTMLElement>('.success');

  if (form && status) {
    const fields = ['name', 'email', 'message'] as const;
    const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]');

    const readValues = (): ContactValues => {
      const data = new FormData(form);
      const get = (key: string) => {
        const value = data.get(key);
        return typeof value === 'string' ? value : '';
      };
      return { name: get('name'), email: get('email'), message: get('message') };
    };

    const showErrors = (errors: ContactErrors) => {
      for (const field of fields) {
        const message = errors[field] ?? '';
        const output = form.querySelector<HTMLElement>(`[data-error-for="${field}"]`);
        if (output) output.textContent = message;
        const control = form.elements.namedItem(field);
        if (control instanceof HTMLElement) {
          if (message) control.setAttribute('aria-invalid', 'true');
          else control.removeAttribute('aria-invalid');
        }
      }
    };

    const showSuccess = (message: string) => {
      status.textContent = message;
      status.hidden = false;
    };

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      status.hidden = true;
      status.textContent = '';
      const values = readValues();
      const errors = validateContact(values);
      showErrors(errors);
      const firstInvalid = fields.find((field) => errors[field]);
      if (firstInvalid) {
        const control = form.elements.namedItem(firstInvalid);
        if (control instanceof HTMLElement) control.focus();
        return;
      }

      if (submit) submit.disabled = true;
      try {
        const response = await fetch(form.action, {
          method: 'POST',
          body: new URLSearchParams(values as unknown as Record<string, string>),
          headers: { Accept: 'application/json' },
        });
        const result: { ok: boolean; message?: string; errors?: ContactErrors } = await response.json();
        if (result.ok) {
          form.reset();
          showSuccess(result.message ?? successMessage(values.name));
        } else {
          showErrors(result.errors ?? {});
        }
      } catch {
        // Network failure: fall back to a regular form post.
        form.submit();
      } finally {
        if (submit) submit.disabled = false;
      }
    });
  }
</script>
EOF
